const dupData = $('Check Duplicates').all();
const orphanData = $('Check Orphans').all();
const now = new Date().toISOString();
let report = '# Weekly Lint - ' + now + '\n\n## Duplicates\n';
if (dupData.length > 0) {
  dupData.forEach(d => { report += '- ' + d.json.file_hash + ': ' + d.json.cnt + '\n'; });
} else { report += 'none\n'; }
report += '\n## Orphan chunks\n';
if (orphanData.length > 0) {
  orphanData.forEach(o => { report += '- ' + o.json.chunk_id + '\n'; });
} else { report += 'none\n'; }
return [{ json: { report: report, checked_at: now } }];
